import { useState } from 'react';
import { Amount, Badge, Button, Card, CardBody, CardFooter, CardHeader, List, ListItem, TabItem, TabList, Tabs } from '@greenloom-ai/weft';
import { RiArrowRightUpLine, RiCheckboxCircleFill } from '@remixicon/react';

const plan = {
  name: 'Pro plan',
  description: 'For finance teams closing every month',
  monthlyPrice: 49,
  annualMonthlyPrice: 39,
  features: [
    'Unlimited reconciliation runs',
    'Up to 10 connected bank sources',
    'Priority support within 4 hours',
  ],
};

const annualTotal = plan.annualMonthlyPrice * 12;
const annualSaving = plan.monthlyPrice * 12 - annualTotal;
const savingPercent = Math.round((annualSaving / (plan.monthlyPrice * 12)) * 100);

export default function Design() {
  const [cycle, setCycle] = useState('annual');
  const isAnnual = cycle === 'annual';
  const price = isAnnual ? plan.annualMonthlyPrice : plan.monthlyPrice;

  return (
    <Card className="w-80">
      <CardHeader
        title={plan.name}
        description={plan.description}
      />
      <CardBody>
        <div className="flex flex-col gap-5">
          <Tabs variant="filled" value={cycle} onChange={setCycle} isFullWidthTabItem>
            <TabList accessibilityLabel="Billing cycle">
              <TabItem value="monthly">Monthly</TabItem>
              <TabItem
                value="annual"
                trailing={<Badge color="positive" size="small">{`Save ${savingPercent}%`}</Badge>}
              >
                Annual
              </TabItem>
            </TabList>
          </Tabs>
          <div className="flex flex-col gap-1">
            <div className="flex items-baseline gap-1">
              <Amount value={price} currency="USD" size="xlarge" />
              <span className="type-body-sm text-content-muted-foreground">/ month</span>
            </div>
            {isAnnual ? (
              <div className="flex flex-wrap items-baseline gap-1 type-body-xs text-content-muted-foreground">
                <span>Billed</span>
                <Amount value={annualTotal} currency="USD" size="small" />
                <span>yearly · you save</span>
                <Amount value={annualSaving} currency="USD" size="small" color="positive" />
              </div>
            ) : (
              <div className="flex flex-wrap items-baseline gap-1 type-body-xs text-content-muted-foreground">
                <span>Switch to annual and save</span>
                <Amount value={annualSaving} currency="USD" size="small" />
                <span>a year</span>
              </div>
            )}
          </div>
          <List icon={RiCheckboxCircleFill} size="medium" accessibilityLabel="Included in Pro">
            {plan.features.map((f) => (
              <ListItem key={f}>{f}</ListItem>
            ))}
          </List>
        </div>
      </CardBody>
      <CardFooter>
        <Button isFullWidth icon={RiArrowRightUpLine} iconPosition="right">
          Upgrade to Pro
        </Button>
      </CardFooter>
    </Card>
  );
}

import { useState } from 'react';
import { Amount, Badge, Button, Card, CardBody, CardFooter, CardHeader, Radio, RadioGroup } from '@greenloom-ai/weft';
import { RiArrowRightUpLine } from '@remixicon/react';

const plan = {
  name: 'Pro plan',
  monthlyPrice: 49,
  annualMonthlyPrice: 39,
  features: [
    'Unlimited reconciliation runs',
    'Up to 10 connected bank sources',
    'Priority support within 4 hours',
  ],
};

const annualSaving = (plan.monthlyPrice - plan.annualMonthlyPrice) * 12;

export default function Design() {
  const [cycle, setCycle] = useState('monthly');
  const isAnnual = cycle === 'annual';

  return (
    <Card className="w-80">
      <CardHeader title="Choose how to pay" description="Pro plan · 3 features included" />
      <CardBody>
        <RadioGroup
          label="Billing cycle"
          name="billingCycle"
          value={cycle}
          onChange={({ value }) => setCycle(value)}
        >
          <Radio value="monthly" helpText="Billed every month, cancel anytime">
            <span className="flex items-baseline gap-1">
              Monthly ·
              <Amount value={plan.monthlyPrice} currency="USD" size="medium" />
              <span>/ mo</span>
            </span>
          </Radio>
          <Radio
            value="annual"
            helpText={
              <span className="flex flex-wrap items-baseline gap-1">
                <span>Billed yearly · save</span>
                <Amount value={annualSaving} currency="USD" size="small" color="positive" />
              </span>
            }
          >
            <span className="flex items-center gap-2">
              <span className="flex items-baseline gap-1">
                Annual ·
                <Amount value={plan.annualMonthlyPrice} currency="USD" size="medium" />
                <span>/ mo</span>
              </span>
              <Badge color="positive" size="small">Save 20%</Badge>
            </span>
          </Radio>
        </RadioGroup>
      </CardBody>
      <CardFooter>
        <Button isFullWidth icon={RiArrowRightUpLine} iconPosition="right">
          {isAnnual ? 'Upgrade annually' : 'Upgrade monthly'}
        </Button>
      </CardFooter>
    </Card>
  );
}

